    targetQuery: `SELECT t.token_id, t.developer_id, t.environment,\n       COUNT(r.log_id) AS total_requests_served,\n       CASE\n         WHEN COUNT(r.log_id) = 0 THEN 'DORMANT_TOKEN_NEEDS_REVOCATION'\n         ELSE 'ACTIVE_IN_USE'\n       END AS token_lifecycle_status\nFROM ApiTokens t\nLEFT JOIN RequestLogs r\n  ON t.token_id = r.token_id\nGROUP BY t.token_id, t.developer_id, t.environment\nORDER BY total_requests_served ASC;`,
