    schemaSnippet: "`ProductCatalog (sku VARCHAR(32) PRIMARY KEY, product_name VARCHAR(100), category VARCHAR(32), units_sold INT)` & `ReturnClaims (rma_id VARCHAR(32) PRIMARY KEY, sku VARCHAR(32), refund_usd DECIMAL(8,2))`",
    targetQuery: `SELECT p.sku, p.product_name, p.category, p.units_sold,\n       COUNT(r.rma_id) AS units_returned,\n       COALESCE(SUM(r.refund_usd), 0.00) AS total_refunded_usd,\n       ROUND((COUNT(r.rma_id) * 100.0) / NULLIF(p.units_sold, 0), 2) AS return_rate_pct\nFROM ProductCatalog p\nLEFT JOIN ReturnClaims r\n  ON p.sku = r.sku\nWHERE p.units_sold > 50\nGROUP BY p.sku, p.product_name, p.category, p.units_sold\nORDER BY return_rate_pct ASC;`,
    eli5Story: "Finding the best quality products that customers loved so much they never returned a single one (0% return rate).",
