    schemaSnippet: "`SupplierMaster (supplier_id VARCHAR(32) PRIMARY KEY, supplier_name VARCHAR(100), total_po_volume_usd DECIMAL(14,2))` & `WarrantyDefects (defect_id VARCHAR(32) PRIMARY KEY, supplier_id VARCHAR(32), claim_cost_usd DECIMAL(10,2), defect_type VARCHAR(32))`",
    targetQuery: `SELECT s.supplier_id, s.supplier_name, s.total_po_volume_usd,\n       COUNT(w.defect_id) AS total_defect_claims,\n       COALESCE(SUM(w.claim_cost_usd), 0.00) AS total_claim_liability_usd,\n       ROUND((COALESCE(SUM(w.claim_cost_usd), 0.00) / s.total_po_volume_usd) * 100.0, 3) AS defect_cost_pct,\n       CASE\n         WHEN COUNT(w.defect_id) = 0 THEN 'EXCELLENT_ZERO_DEFECT_TIER'\n         WHEN (COALESCE(SUM(w.claim_cost_usd), 0.00) / s.total_po_volume_usd) * 100.0 <= 1.0 THEN 'ACCEPTABLE_TIER'\n         ELSE 'DEFECT_PENALTY_TIER'\n       END AS vendor_quality_rating\nFROM SupplierMaster s\nLEFT JOIN WarrantyDefects w\n  ON s.supplier_id = w.supplier_id\nGROUP BY s.supplier_id, s.supplier_name, s.total_po_volume_usd\nORDER BY defect_cost_pct ASC;`,
